import { line } from 'axylo';

/**
 * The line chart's options for the rows of data.json.
 * Kept separate from render() so the same options can be checked with validate() in Node.
 *
 * @param {ReadonlyArray<{ day: string, signpus: number | null }>} data rows from data.json
 */
export function chartOptions(data) {
  return {
    title: 'Daily signups',
    data,
    // 'YYYY-MM-DD' strings are calendar days; declaring it keeps them days in every time zone.
    x: { field: 'day', type: 'date' },
    // data.json spells this key "signpus". The label gives readers the right word
    // in the axis title, tooltip, table and announcements.
    y: { field: 'signpus', label: 'Signups' },
  };
}

/**
 * Draws the daily signups line chart into `element`.
 *
 * @param {HTMLElement} element the chart container
 * @param {ReadonlyArray<{ day: string, signpus: number | null }>} data rows from data.json
 * @returns the Axylo chart handle (update(), destroy(), diagnostics, ...)
 */
export default function render(element, data) {
  return line(element, chartOptions(data));
}

