input.command:
node --input-type=module -e "
import { readFileSync } from 'node:fs';
import { validate } from 'axylo';
import render, { chartOptions } from './chart.js';

const rows = JSON.parse(readFileSync('data.json', 'utf8'));
console.log('render is a function of arity', typeof render, render.length);

const problems = validate('line', chartOptions(rows));
console.log('Diagnostics for chart.js options:', problems.length);
for (const d of problems) console.log(' ', d.code, d.level, d.message);

// Control: the spelling the prompt uses is not the key in the data.
const control = validate('line', { ...chartOptions(rows), y: { field: 'signups', label: 'Signups' } });
for (const d of control) console.log('control:', d.code, d.level, d.message);
"

